// RVC-Train-GGML - training-state GGUF loading (src/model/weights.h)
//
// Training-state GGUF (generated by tools/pth_to_train_gguf.py, metadata prefix rvc.train.*):
//   - tensor names = torch state_dict key names (including weight_g/weight_v, not folded)
//   - shapes are in ggml/traincpp ne order (torch shape reversed)
//
// This module only handles "open + metadata + load by name + shape validation",
// and contains no RVC model structure knowledge (model assembly lives in the M2 src/model/ layer modules).
#pragma once

#include "traincpp/traincpp.h"

#include <array>
#include <string>
#include <vector>

namespace rvc_train {
namespace model {

// Training-state GGUF metadata (rvc.train.*; missing fields are 0/empty)
struct TrainMeta {
    std::string kind;              // "G" | "D"
    std::string version;           // "v1" | "v2"
    bool        has_f0 = false;
    std::string form;              // "train" | "small" | "raw"
    std::string source_pth;
    std::string out_dtype;         // "F32" | "F16"
    int64_t     tensor_count = 0;

    int64_t sample_rate  = 0;
    int64_t spec_channels = 0;
    int64_t filter_length = 0;
    int64_t hop_length    = 0;
    int64_t win_length    = 0;
    int64_t n_mel_channels = 0;
    float   mel_fmin = 0.0f;
    float   mel_fmax = 0.0f;
    int64_t segment_size = 0;

    int64_t inter_channels  = 0;
    int64_t hidden_channels = 0;
    int64_t filter_channels = 0;
    int64_t n_heads         = 0;
    int64_t n_layers        = 0;
    int64_t kernel_size     = 0;
    float   p_dropout       = 0.0f;
    int64_t gin_channels    = 0;
    int64_t spk_embed_dim   = 0;
    int64_t upsample_initial_channel = 0;
    std::string resblock;
    std::vector<int32_t> resblock_kernel_sizes;
    std::vector<int32_t> resblock_dilation_sizes;   // flattened (3 kernels × 3 dilations)
    std::vector<int32_t> upsample_rates;
    std::vector<int32_t> upsample_kernel_sizes;

    std::vector<int32_t> d_periods;                 // D model: discriminator periods
};

// Training-state GGUF (read-only). If the file does not exist / is malformed, open returns nullptr with an error.
class TrainWeights {
public:
    static TrainWeights* open(const std::string& path, std::string* err);
    ~TrainWeights();

    TrainWeights(const TrainWeights&) = delete;
    TrainWeights& operator=(const TrainWeights&) = delete;

    const std::string& path() const { return path_; }
    int64_t tensor_count() const { return count_; }
    const char* tensor_name(int64_t index) const;   // returns nullptr if out of range

    bool has(const char* name) const;
    // ne of the tensor in the file (4 dims, padded with 1); returns false if name does not exist
    bool tensor_ne(const char* name, std::array<int64_t, 4>* ne) const;
    // tensor type in the file (returns TYPE_F32 and prints an error if not found)
    traincpp::Type tensor_type(const char* name) const;

    bool read_meta(TrainMeta* meta) const;

    // Create an F32 tensor in ctx with the file's shape (returns nullptr if the name does not exist)
    traincpp::Tensor* new_tensor(traincpp::Context* ctx, const char* name) const;

    // Load into an already-created tensor by name:
    //   - name missing, shape mismatch with the file, dst not F32, or data not allocated -> returns false with a clear error
    bool load(traincpp::Tensor* dst, const char* name, std::string* err) const;

    // Expected manifest validation (for M2 model assembly):
    //   missing    = expected but not present in the file
    //   mismatched = present but ne does not match
    struct Expect {
        std::string name;
        std::array<int64_t, 4> ne{1, 1, 1, 1};
    };
    void check_expected(const std::vector<Expect>& expected, std::vector<std::string>* missing,
                        std::vector<std::string>* mismatched) const;

private:
    TrainWeights() = default;

    traincpp::GgufFile* file_ = nullptr;
    std::string path_;
    int64_t count_ = 0;
};

} // namespace model
} // namespace rvc_train
